class_name SummerThirdPersonController
extends CharacterBody3D

## Canonical controller for a playable Summer humanoid character package.
## Copy this file unchanged first. Customize the copy only when the user asks.

const REQUIRED_ROLES: Array[StringName] = [&"idle", &"walk", &"run", &"jump"]
const REQUIRED_ACTIONS: Array[StringName] = [
	&"move_left",
	&"move_right",
	&"move_forward",
	&"move_back",
	&"jump",
	&"sprint",
	&"ui_cancel",
]

@export_file("*.json") var character_manifest_path: String

@export_category("Movement")
@export var walk_speed: float = 4.0
@export var run_speed: float = 7.0
@export var acceleration: float = 24.0
@export var jump_velocity: float = 5.5
@export var turn_speed: float = 12.0
@export var floor_snap_distance: float = 0.3
@export var floor_stick_velocity: float = 0.5

@export_category("Camera")
@export var mouse_sensitivity: float = 0.002
@export var camera_height: float = 1.5
@export var camera_distance: float = 4.5
@export_flags_3d_physics var camera_collision_mask: int = 1
@export var camera_pitch_degrees: float = -20.0

@export_category("Respawn")
@export var respawn_below_y: float = -15.0

@export_category("Required Nodes")
@export_node_path("Node3D") var visual_root_path: NodePath = ^"CharacterRotationRoot"
@export_node_path("Node3D") var camera_yaw_path: NodePath = ^"CameraYaw"
@export_node_path("Node3D") var camera_pitch_path: NodePath = ^"CameraYaw/CameraPitch"
@export_node_path("SpringArm3D") var spring_arm_path: NodePath = ^"CameraYaw/CameraPitch/SpringArm3D"
@export_node_path("AnimationPlayer") var animation_player_path: NodePath = ^"CharacterRotationRoot/Character/Visual/AnimationPlayer"

@onready var _visual_root: Node3D = get_node(visual_root_path) as Node3D
@onready var _camera_yaw: Node3D = get_node(camera_yaw_path) as Node3D
@onready var _camera_pitch: Node3D = get_node(camera_pitch_path) as Node3D
@onready var _spring_arm: SpringArm3D = get_node(spring_arm_path) as SpringArm3D
@onready var _animation_player: AnimationPlayer = get_node(animation_player_path) as AnimationPlayer

var _gravity: float = 0.0
var _spawn_position: Vector3
var _clips_by_role: Dictionary = {}
var _active_role: StringName = &""


func _ready() -> void:
	_validate_scene_contract()
	_gravity = float(ProjectSettings.get_setting("physics/3d/default_gravity"))
	_spawn_position = global_position
	floor_snap_length = floor_snap_distance
	_camera_yaw.position.y = camera_height
	_camera_pitch.rotation = Vector3(deg_to_rad(camera_pitch_degrees), 0.0, 0.0)
	_spring_arm.spring_length = camera_distance
	_spring_arm.collision_mask = camera_collision_mask
	_spring_arm.add_excluded_object(get_rid())
	_configure_character_animation()
	_play_role(&"idle")
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed(&"ui_cancel"):
		Input.mouse_mode = Input.MOUSE_MODE_VISIBLE
		return
	if event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		Input.mouse_mode = Input.MOUSE_MODE_CAPTURED
	if Input.mouse_mode != Input.MOUSE_MODE_CAPTURED:
		return
	if event is InputEventMouseMotion:
		_camera_yaw.rotate_y(-event.screen_relative.x * mouse_sensitivity)


func _physics_process(delta: float) -> void:
	var was_on_floor := is_on_floor()
	if was_on_floor:
		# A small downward velocity keeps the body snapped to flat and gently
		# descending floors instead of producing a one-frame false airborne state.
		velocity.y = -floor_stick_velocity
	else:
		velocity.y -= _gravity * delta
	if Input.is_action_just_pressed(&"jump") and was_on_floor:
		velocity.y = jump_velocity

	var input_vector: Vector2 = Input.get_vector(
		&"move_left",
		&"move_right",
		&"move_forward",
		&"move_back"
	)
	var camera_forward: Vector3 = -_camera_yaw.global_transform.basis.z
	var camera_right: Vector3 = _camera_yaw.global_transform.basis.x
	camera_forward.y = 0.0
	camera_right.y = 0.0
	camera_forward = camera_forward.normalized()
	camera_right = camera_right.normalized()
	var movement_direction: Vector3 = (
		camera_right * input_vector.x + camera_forward * -input_vector.y
	)
	if movement_direction.length_squared() > 1.0:
		movement_direction = movement_direction.normalized()

	var is_sprinting: bool = Input.is_action_pressed(&"sprint")
	var target_speed: float = run_speed if is_sprinting else walk_speed
	var target_velocity: Vector3 = movement_direction * target_speed
	velocity.x = move_toward(velocity.x, target_velocity.x, acceleration * delta)
	velocity.z = move_toward(velocity.z, target_velocity.z, acceleration * delta)

	move_and_slide()
	_turn_visual_toward(movement_direction, delta)
	_update_animation_state(is_sprinting)
	if global_position.y < respawn_below_y:
		global_position = _spawn_position
		velocity = Vector3.ZERO
		_play_role(&"idle")


func _validate_scene_contract() -> void:
	assert(_visual_root != null, "Missing CharacterRotationRoot")
	assert(_camera_yaw != null, "Missing CameraYaw")
	assert(_camera_pitch != null, "Missing CameraPitch")
	assert(_spring_arm != null, "Missing SpringArm3D")
	assert(_animation_player != null, "Missing character AnimationPlayer")
	assert(character_manifest_path != "", "Set character_manifest_path")
	for action in REQUIRED_ACTIONS:
		assert(InputMap.has_action(action), "Missing input action: %s" % action)


func _configure_character_animation() -> void:
	var file := FileAccess.open(character_manifest_path, FileAccess.READ)
	assert(file != null, "Missing character manifest: %s" % character_manifest_path)
	var manifest = JSON.parse_string(file.get_as_text())
	assert(manifest is Dictionary, "Invalid character manifest JSON")
	assert(manifest.get("status") == "ready", "Character package is not ready")
	assert(
		manifest.get("normalization", {}).get("forwardAxis") == "-Z",
		"Character package forward axis must be -Z"
	)

	for entry in manifest.get("animations", []):
		if not entry is Dictionary:
			continue
		var role := StringName(String(entry.get("semanticRole", "")).to_lower())
		if role not in REQUIRED_ROLES:
			continue
		var clip := StringName(String(entry.get("name", "")))
		assert(clip != &"", "Requested character role has no clip: %s" % role)
		assert(not _clips_by_role.has(role), "Ambiguous character role: %s" % role)
		assert(_animation_player.has_animation(clip), "Manifest clip is not playable: %s" % clip)
		_clips_by_role[role] = clip

	for role in REQUIRED_ROLES:
		assert(_clips_by_role.has(role), "Missing requested character role: %s" % role)
	for role in [&"idle", &"walk", &"run"]:
		_animation_player.get_animation(_clips_by_role[role]).loop_mode = Animation.LOOP_LINEAR
	_animation_player.get_animation(_clips_by_role[&"jump"]).loop_mode = Animation.LOOP_NONE


func _update_animation_state(is_sprinting: bool) -> void:
	var horizontal_speed := Vector2(velocity.x, velocity.z).length()
	var next_role: StringName
	if not is_on_floor():
		next_role = &"jump"
	elif horizontal_speed <= 0.05:
		next_role = &"idle"
	elif is_sprinting:
		next_role = &"run"
	else:
		next_role = &"walk"
	_play_role(next_role)


func _play_role(role: StringName) -> void:
	assert(_clips_by_role.has(role), "Missing requested character role: %s" % role)
	if role == _active_role:
		return
	_animation_player.play(_clips_by_role[role])
	# Apply the first keyed pose immediately. This prevents a visible bind-pose
	# frame while the AnimationPlayer waits for its next process tick.
	_animation_player.advance(0.0)
	_active_role = role


func _turn_visual_toward(direction: Vector3, delta: float) -> void:
	if direction.length_squared() <= 0.0001:
		return
	var local_direction: Vector3 = global_transform.basis.inverse() * direction
	var target_yaw := atan2(-local_direction.x, -local_direction.z)
	var weight := 1.0 - exp(-turn_speed * delta)
	_visual_root.rotation.y = lerp_angle(_visual_root.rotation.y, target_yaw, weight)

# Condition-Based Waiting

## Overview

Flaky tests often guess at timing with arbitrary delays. This creates race conditions where tests pass on fast machines but fail under load or in CI.

**Core principle:** Wait for the actual condition you care about, not a guess about how long it takes.

## When to Use

```dot
digraph when_to_use {
    "Test uses setTimeout/sleep?" [shape=diamond];
    "Testing timing behavior?" [shape=diamond];
    "Document WHY timeout needed" [shape=box];
    "Use condition-based waiting" [shape=box];

    "Test uses setTimeout/sleep?" -> "Testing timing behavior?" [label="yes"];
    "Testing timing behavior?" -> "Document WHY timeout needed" [label="yes"];
    "Testing timing behavior?" -> "Use condition-based waiting" [label="no"];
}
```

**Use when:**
- Tests have arbitrary delays (`setTimeout`, `sleep`, `time.sleep()`)
- Tests are flaky (pass sometimes, fail under load)
- Tests timeout when run in parallel
- Waiting for async operations to complete

**Don't use when:**
- Testing actual timing behavior (debounce, throttle intervals)
- Always document WHY if using arbitrary timeout

## Core Pattern

```typescript
// BEFORE: Guessing at timing
await new Promise(r => setTimeout(r, 50));
const result = getResult();
expect(result).toBeDefined();

// AFTER: Waiting for condition
await waitFor(() => getResult() !== undefined);
const result = getResult();
expect(result).toBeDefined();
```

## Quick Patterns

| Scenario | Pattern |
|----------|---------|
| Wait for event | `waitFor(() => events.find(e => e.type === 'DONE'))` |
| Wait for state | `waitFor(() => machine.state === 'ready')` |
| Wait for count | `waitFor(() => items.length >= 5)` |
| Wait for file | `waitFor(() => fs.existsSync(path))` |
| Complex condition | `waitFor(() => obj.ready && obj.value > 10)` |

## Implementation

Generic polling function:
```typescript
async function waitFor<T>(
  condition: () => T | undefined | null | false,
  description: string,
  timeoutMs = 5000
): Promise<T> {
  const startTime = Date.now();

  while (true) {
    const result = condition();
    if (result) return result;

    if (Date.now() - startTime > timeoutMs) {
      throw new Error(`Timeout waiting for ${description} after ${timeoutMs}ms`);
    }

    await new Promise(r => setTimeout(r, 10)); // Poll every 10ms
  }
}
```

## Common Mistakes

**Bad: Polling too fast:** `setTimeout(check, 1)` - wastes CPU
**Fix:** Poll every 10ms

**No timeout:** Loop forever if condition never met
**Fix:** Always include timeout with clear error

**Stale data:** Cache state before loop
**Fix:** Call getter inside loop for fresh data

## When Arbitrary Timeout IS Correct

```typescript
// Tool ticks every 100ms - need 2 ticks to verify partial output
await waitForEvent(manager, 'TOOL_STARTED'); // First: wait for condition
await new Promise(r => setTimeout(r, 200));   // Then: wait for timed behavior
// 200ms = 2 ticks at 100ms intervals - documented and justified
```

**Requirements:**
1. First wait for triggering condition
2. Based on known timing (not guessing)
3. Comment explaining WHY

# Defense-in-Depth Validation

## Overview

When you fix a bug caused by invalid data, adding validation at one place feels sufficient. But that single check can be bypassed by different code paths, refactoring, or mocks.

**Core principle:** Validate at EVERY layer data passes through. Make the bug structurally impossible.

## Why Multiple Layers

Single validation: "We fixed the bug"
Multiple layers: "We made the bug impossible"

Different layers catch different cases:
- Entry validation catches most bugs
- Business logic catches edge cases
- Environment guards prevent context-specific dangers
- Debug logging helps when other layers fail

## The Four Layers

### Layer 1: Entry Point Validation
**Purpose:** Reject obviously invalid input at API boundary

```typescript
function createProject(name: string, workingDirectory: string) {
  if (!workingDirectory || workingDirectory.trim() === '') {
    throw new Error('workingDirectory cannot be empty');
  }
  if (!existsSync(workingDirectory)) {
    throw new Error(`workingDirectory does not exist: ${workingDirectory}`);
  }
  if (!statSync(workingDirectory).isDirectory()) {
    throw new Error(`workingDirectory is not a directory: ${workingDirectory}`);
  }
  // ... proceed
}
```

### Layer 2: Business Logic Validation
**Purpose:** Ensure data makes sense for this operation

```typescript
function initializeWorkspace(projectDir: string, sessionId: string) {
  if (!projectDir) {
    throw new Error('projectDir required for workspace initialization');
  }
  // ... proceed
}
```

### Layer 3: Environment Guards
**Purpose:** Prevent dangerous operations in specific contexts

```typescript
async function gitInit(directory: string) {
  // In tests, refuse git init outside temp directories
  if (process.env.NODE_ENV === 'test') {
    const normalized = normalize(resolve(directory));
    const tmpDir = normalize(resolve(tmpdir()));

    if (!normalized.startsWith(tmpDir)) {
      throw new Error(
        `Refusing git init outside temp dir during tests: ${directory}`
      );
    }
  }
  // ... proceed
}
```

### Layer 4: Debug Instrumentation
**Purpose:** Capture context for forensics

```typescript
async function gitInit(directory: string) {
  const stack = new Error().stack;
  logger.debug('About to git init', {
    directory,
    cwd: process.cwd(),
    stack,
  });
  // ... proceed
}
```

## Applying the Pattern

When you find a bug:

1. **Trace the data flow** - Where does bad value originate? Where used?
2. **Map all checkpoints** - List every point data passes through
3. **Add validation at each layer** - Entry, business, environment, debug
4. **Test each layer** - Try to bypass layer 1, verify layer 2 catches it

## Example from Session

Bug: Empty `projectDir` caused `git init` in source code

**Data flow:**
1. Test setup → empty string
2. `Project.create(name, '')`
3. `WorkspaceManager.createWorkspace('')`
4. `git init` runs in `process.cwd()`

**Four layers added:**
- Layer 1: `Project.create()` validates not empty/exists/writable
- Layer 2: `WorkspaceManager` validates projectDir not empty
- Layer 3: `WorktreeManager` refuses git init outside tmpdir in tests
- Layer 4: Stack trace logging before git init

**Result:** All 1847 tests passed, bug impossible to reproduce

## Key Insight

All four layers were necessary. During testing, each layer caught bugs the others missed:
- Different code paths bypassed entry validation
- Mocks bypassed business logic checks
- Edge cases on different platforms needed environment guards
- Debug logging identified structural misuse

**Don't stop at one validation point.** Add checks at every layer.

# Root Cause Tracing

## Overview

Bugs often manifest deep in the call stack (git init in wrong directory, file created in wrong location, database opened with wrong path). Your instinct is to fix where the error appears, but that's treating a symptom.

**Core principle:** Trace backward through the call chain until you find the original trigger, then fix at the source.

## When to Use

```dot
digraph when_to_use {
    "Bug appears deep in stack?" [shape=diamond];
    "Can trace backwards?" [shape=diamond];
    "Fix at symptom point" [shape=box];
    "Trace to original trigger" [shape=box];
    "BETTER: Also add defense-in-depth" [shape=box];

    "Bug appears deep in stack?" -> "Can trace backwards?" [label="yes"];
    "Can trace backwards?" -> "Trace to original trigger" [label="yes"];
    "Can trace backwards?" -> "Fix at symptom point" [label="no - dead end"];
    "Trace to original trigger" -> "BETTER: Also add defense-in-depth";
}
```

**Use when:**
- Error happens deep in execution (not at entry point)
- Stack trace shows long call chain
- Unclear where invalid data originated
- Need to find which test/code triggers the problem

## The Tracing Process

### 1. Observe the Symptom
```
Error: git init failed in ~/project/packages/core
```

### 2. Find Immediate Cause
**What code directly causes this?**
```typescript
await execFileAsync('git', ['init'], { cwd: projectDir });
```

### 3. Ask: What Called This?
```typescript
WorktreeManager.createSessionWorktree(projectDir, sessionId)
  → called by Session.initializeWorkspace()
  → called by Session.create()
  → called by test at Project.create()
```

### 4. Keep Tracing Up
**What value was passed?**
- `projectDir = ''` (empty string!)
- Empty string as `cwd` resolves to `process.cwd()`
- That's the source code directory!

### 5. Find Original Trigger
**Where did empty string come from?**
```typescript
const context = setupCoreTest(); // Returns { tempDir: '' }
Project.create('name', context.tempDir); // Accessed before beforeEach!
```

## Adding Stack Traces

When you can't trace manually, add instrumentation:

```typescript
// Before the problematic operation
async function gitInit(directory: string) {
  const stack = new Error().stack;
  console.error('DEBUG git init:', {
    directory,
    cwd: process.cwd(),
    nodeEnv: process.env.NODE_ENV,
    stack,
  });

  await execFileAsync('git', ['init'], { cwd: directory });
}
```

**Critical:** Use `console.error()` in tests (not logger - may not show)

**Run and capture:**
```bash
npm test 2>&1 | grep 'DEBUG git init'
```

**Analyze stack traces:**
- Look for test file names
- Find the line number triggering the call
- Identify the pattern (same test? same parameter?)

## Finding Which Test Causes Pollution

If something appears during tests but you don't know which test:

Bisect: run the test files one at a time (or in halves) and check for the artifact after each run. The first run that produces it is the polluter. A five-line shell loop over the test files is enough; stop at the first hit.

## Real Example: Empty projectDir

**Symptom:** `.git` created in `packages/core/` (source code)

**Trace chain:**
1. `git init` runs in `process.cwd()` ← empty cwd parameter
2. WorktreeManager called with empty projectDir
3. Session.create() passed empty string
4. Test accessed `context.tempDir` before beforeEach
5. setupCoreTest() returns `{ tempDir: '' }` initially

**Root cause:** Top-level variable initialization accessing empty value

**Fix:** Made tempDir a getter that throws if accessed before beforeEach

**Also added defense-in-depth:**
- Layer 1: Project.create() validates directory
- Layer 2: WorkspaceManager validates not empty
- Layer 3: NODE_ENV guard refuses git init outside tmpdir
- Layer 4: Stack trace logging before git init

## Key Principle

```dot
digraph principle {
    "Found immediate cause" [shape=ellipse];
    "Can trace one level up?" [shape=diamond];
    "Trace backwards" [shape=box];
    "Is this the source?" [shape=diamond];
    "Fix at source" [shape=box];
    "Add validation at each layer" [shape=box];
    "Bug impossible" [shape=doublecircle];
    "NEVER fix just the symptom" [shape=octagon, style=filled, fillcolor=red, fontcolor=white];

    "Found immediate cause" -> "Can trace one level up?";
    "Can trace one level up?" -> "Trace backwards" [label="yes"];
    "Can trace one level up?" -> "NEVER fix just the symptom" [label="no"];
    "Trace backwards" -> "Is this the source?";
    "Is this the source?" -> "Trace backwards" [label="no - keeps going"];
    "Is this the source?" -> "Fix at source" [label="yes"];
    "Fix at source" -> "Add validation at each layer";
    "Add validation at each layer" -> "Bug impossible";
}
```

**NEVER fix just where the error appears.** Trace back to find the original trigger.

## Stack Trace Tips

**In tests:** Use `console.error()` not logger - logger may be suppressed
**Before operation:** Log before the dangerous operation, not after it fails
**Include context:** Directory, cwd, environment variables, timestamps
**Capture stack:** `new Error().stack` shows complete call chain

extends Node3D
## Builds a location's blockout from a JSON spec, so the same file drives the engine and the engine-free
## wireframe preview over the concept (preview.py). Put this node as the location's `Painted` child.
## Spec: {"objects": [{"name", "kind", "color", "solid", ...}]}, metres, y up:
##   box    pos (centre), size [x, y, z], yaw / rot_x / rot_z (degrees), scale
##   prism  pos, size (a PrismMesh: the ridge along z), yaw / rot_x / rot_z
##   cyl    pos (base centre), r_bot, r_top, height
##   sphere pos (centre), radius, sy (vertical squash)
##   poly   points [[x, z], ...], top, depth: flat ground or a quay, extruded down, two-sided collision
##   wall   segments [[[x, z], [x, z]], ...], height: invisible blockers along water and ledges (leave gaps at
##          pier roots and doorways)
## Each solid object gets a StaticBody3D with a matching shape; every mesh gets one flat colour from COLORS that
## tells the painter what it is (the paint-over prompt repeats them as a colour key). Name door and step slabs
## "..._door" / "..._steps": painted_location.gd hides them in the game. A gable roof is two parts: a
## wall-coloured prism for the gable plus two thin slanted roof slabs with overhang; a single roof-coloured prism
## makes the painter paint roof on the gable wall.

@export_file("*.json") var spec := "res://painted/blockout.json"

## Colour key: red tile roof, yellow thatch, dark blue slate, cream plaster, grey stone, brown wood and doors,
## green grass and leaves, pink flower beds, orange lamps and fruit, light brown cobbles and dirt, blue water.
const COLORS := {
	"tile": Color(0.78, 0.25, 0.18), "thatch": Color(0.88, 0.72, 0.32), "slate": Color(0.22, 0.26, 0.42),
	"plaster": Color(0.93, 0.88, 0.76), "stone": Color(0.55, 0.55, 0.55), "rock": Color(0.42, 0.4, 0.44),
	"wood": Color(0.5, 0.33, 0.18), "door": Color(0.42, 0.26, 0.14), "crate": Color(0.66, 0.48, 0.28),
	"grass": Color(0.36, 0.62, 0.25), "leaf": Color(0.2, 0.55, 0.2), "bush": Color(0.3, 0.55, 0.22),
	"bark": Color(0.35, 0.22, 0.12), "flower": Color(0.95, 0.55, 0.75), "lamp": Color(1.0, 0.65, 0.2),
	"cobble": Color(0.72, 0.6, 0.45), "dirt": Color(0.72, 0.56, 0.38), "water": Color(0.1, 0.35, 0.5),
	"canvas": Color(0.9, 0.3, 0.3), "iron": Color(0.15, 0.15, 0.17), "glass": Color(0.35, 0.5, 0.75),
	"floor": Color(0.6, 0.42, 0.25), "rug": Color(0.6, 0.15, 0.2), "fire": Color(1.0, 0.5, 0.1),
	"white": Color(0.97, 0.97, 0.97),
}

func _ready() -> void:
	var data: Dictionary = JSON.parse_string(FileAccess.get_file_as_string(spec))
	for o in data.objects:
		if o.kind == "wall":
			_walls(o)
		else:
			_build(o)

## Invisible collision only: keeps the player out of the water and on the piers.
func _walls(o: Dictionary) -> void:
	var body := StaticBody3D.new()
	body.name = o.name
	for seg in o.segments:
		var a := Vector3(seg[0][0], 0, seg[0][1])
		var b := Vector3(seg[1][0], 0, seg[1][1])
		var cs := CollisionShape3D.new()
		var s := BoxShape3D.new()
		s.size = Vector3(a.distance_to(b) + 0.1, o.height, 0.2)
		cs.shape = s
		cs.position = (a + b) / 2.0 + Vector3(0, o.height / 2.0, 0)
		cs.rotation.y = atan2(-(b.z - a.z), b.x - a.x)
		body.add_child(cs)
	add_child(body)

func _build(o: Dictionary) -> void:
	var mesh: Mesh
	var shape: Shape3D
	var offset := Vector3.ZERO
	match o.kind:
		"box":
			var b := BoxMesh.new()
			b.size = _v(o.size)
			mesh = b
			var s := BoxShape3D.new()
			s.size = b.size
			shape = s
		"prism":
			var p := PrismMesh.new()
			p.size = _v(o.size)
			mesh = p
			shape = p.create_convex_shape()
		"cyl":
			var c := CylinderMesh.new()
			c.top_radius = o.r_top
			c.bottom_radius = o.r_bot
			c.height = o.height
			c.radial_segments = 24
			mesh = c
			offset.y = o.height / 2.0
			var s := CylinderShape3D.new()
			s.radius = maxf(o.r_top, o.r_bot)
			s.height = o.height
			shape = s
		"sphere":
			var sp := SphereMesh.new()
			sp.radius = o.radius
			sp.height = o.radius * 2.0
			mesh = sp
			var s := SphereShape3D.new()
			s.radius = o.radius
			shape = s
		"poly":
			mesh = _extrude(o.points, o.top, o.depth)
			shape = mesh.create_trimesh_shape()
			(shape as ConcavePolygonShape3D).backface_collision = true
	var mi := MeshInstance3D.new()
	mi.name = o.name
	mi.mesh = mesh
	var mat := StandardMaterial3D.new()
	mat.albedo_color = COLORS.get(o.color, Color.MAGENTA)
	mat.cull_mode = BaseMaterial3D.CULL_DISABLED
	mi.material_override = mat
	var holder: Node3D = mi
	if o.get("solid", false):
		var body := StaticBody3D.new()
		body.name = o.name + "Body"
		var cs := CollisionShape3D.new()
		cs.shape = shape
		body.add_child(cs)
		body.add_child(mi)
		holder = body
	if o.kind != "poly":
		holder.position = _v(o.pos) + offset
		holder.rotation_degrees = Vector3(o.get("rot_x", 0.0), o.get("yaw", 0.0), o.get("rot_z", 0.0))
		if o.kind == "sphere" and o.has("sy"):
			mi.scale = Vector3(1, o.sy, 1)
		if o.has("scale"):
			holder.scale = _v(o.scale)
	add_child(holder)

## A flat polygon (x, z points) extruded from top down by depth, with side walls.
func _extrude(points: Array, top: float, depth: float) -> ArrayMesh:
	var pts := PackedVector2Array()
	for p in points:
		pts.append(Vector2(p[0], p[1]))
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var tri := Geometry2D.triangulate_polygon(pts)
	for i in range(0, tri.size(), 3):
		for k in [0, 2, 1]:
			var p := pts[tri[i + k]]
			st.add_vertex(Vector3(p.x, top, p.y))
	for i in pts.size():
		var a := pts[i]
		var b := pts[(i + 1) % pts.size()]
		var a0 := Vector3(a.x, top, a.y)
		var b0 := Vector3(b.x, top, b.y)
		var a1 := a0 - Vector3(0, depth, 0)
		var b1 := b0 - Vector3(0, depth, 0)
		for v in [a0, b0, b1, a0, b1, a1]:
			st.add_vertex(v)
	st.generate_normals()
	return st.commit()

func _v(a: Array) -> Vector3:
	return Vector3(a[0], a[1], a[2])

extends Node
## Renders a location's plain, lit blockout through its PaintCamera into a PNG of an exact size, then quits.
## Make a scene with only this node, set `level` (the world scene) and `camera_path`, and play it. The PNG is the
## structure image for the paint-over. Keep size at the painting's aspect (16:9). Needs a rendering run (the
## editor's play, or a windowed run); a --headless run renders nothing.

@export var level: PackedScene
@export var size := Vector2i(2048, 1152)
@export var out_path := "res://painted/blockout.png"
## The location's paint camera inside `level`.
@export var camera_path := "Village/PaintCamera"

func _ready() -> void:
	var vp := SubViewport.new()
	vp.size = size
	vp.render_target_update_mode = SubViewport.UPDATE_ALWAYS
	vp.own_world_3d = true
	add_child(vp)
	var lvl := level.instantiate()
	# no painting: painted_world.gd then shows the plain blockout, lit, through the paint camera
	for node in lvl.find_children("*", "Node3D", true, false):
		if "paint" in node:
			node.paint = null
	vp.add_child(lvl)
	await get_tree().process_frame
	(lvl.get_node(camera_path) as Camera3D).make_current()
	for i in 4:
		await RenderingServer.frame_post_draw
	var img := vp.get_texture().get_image()
	img.save_png(out_path)
	print("PAINT_VIEW_SAVED ", ProjectSettings.globalize_path(out_path), " ", img.get_size())
	get_tree().quit()

// Projects one painted picture onto every mesh that uses this material, from the fixed paint camera.
// UV = where the surface point sits in the paint camera's orthographic frame, so no mesh needs UVs.
// Unshaded: the painting already holds all the light. Keep the scene tonemap Linear, exposure 1.
shader_type spatial;
render_mode unshaded, cull_disabled, shadows_disabled;

uniform sampler2D paint : source_color, filter_linear_mipmap_anisotropic, repeat_disable;
uniform vec3 paint_origin;      // PaintCamera.global_position
uniform vec3 paint_right;       // PaintCamera.global_basis.x
uniform vec3 paint_up;          // PaintCamera.global_basis.y
uniform vec2 paint_size;        // frame width, height in metres (Camera3D.size with KEEP_WIDTH, height = width * H / W)

varying vec3 world_pos;

void vertex() {
	world_pos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
}

void fragment() {
	vec3 d = world_pos - paint_origin;
	vec2 uv = vec2(dot(d, paint_right) / paint_size.x + 0.5, 0.5 - dot(d, paint_up) / paint_size.y);
	ALBEDO = texture(paint, uv).rgb;
}

