extends Node3D
## One painted frame: a PaintCamera, the blockout under Painted, and the paint-over projected onto it from
## that camera. With no `paint` set it shows the plain blockout (play it and capture that frame for the paint-over).
## Children: PaintCamera (Camera3D, orthographic, KEEP_WIDTH), Painted (Node3D with every block).

const PROJECTION := preload("res://painted/paint_projection.gdshader")

## The paint-over for this frame (4K, imported lossless).
@export var paint: Texture2D
## Rooms: frame the whole painting like a stage. Outdoors: follow the player.
@export var frame_whole := false

@onready var paint_cam: Camera3D = $PaintCamera
var paint_size := Vector2.ZERO
## Average colour along the painting's border: the clear colour while the player is here.
var edge_color := Color(0.1, 0.1, 0.1)

func _ready() -> void:
	if paint == null:
		return
	paint_size = Vector2(paint_cam.size, paint_cam.size * paint.get_height() / float(paint.get_width()))
	var mat := ShaderMaterial.new()
	mat.shader = PROJECTION
	mat.set_shader_parameter("paint", paint)
	mat.set_shader_parameter("paint_origin", paint_cam.global_position)
	mat.set_shader_parameter("paint_right", paint_cam.global_basis.x)
	mat.set_shader_parameter("paint_up", paint_cam.global_basis.y)
	mat.set_shader_parameter("paint_size", paint_size)
	for mi in $Painted.find_children("*", "MeshInstance3D", true, false):
		# door slabs and steps stick out of the walls in the blockout; the painting already shows them
		if mi.name.containsn("door") or mi.name.containsn("steps"):
			mi.visible = false
			continue
		(mi as MeshInstance3D).material_override = mat
		(mi as MeshInstance3D).cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	edge_color = _edge_color()

## Where p sits in this frame's picture plane, in metres from the frame centre.
func plane(p: Vector3) -> Vector2:
	var d := p - paint_cam.global_position
	return Vector2(d.dot(paint_cam.global_basis.x), d.dot(paint_cam.global_basis.y))

func _edge_color() -> Color:
	var img := paint.get_image()
	if img == null:
		return edge_color
	if img.is_compressed():
		img.decompress()
	var w := img.get_width() - 1
	var h := img.get_height() - 1
	var sum := Color(0, 0, 0, 0)
	for i in 32:
		var t := i / 31.0
		for p in [Vector2i(int(t * w), 0), Vector2i(int(t * w), h), Vector2i(0, int(t * h)), Vector2i(w, int(t * h))]:
			sum += img.get_pixelv(p)
	return Color(sum.r / 128.0, sum.g / 128.0, sum.b / 128.0)

extends CharacterBody3D
## Sprite character on a capsule. Input moves in screen directions: up = away from the camera on the ground.
## The sprite is a vertical Y-billboard, stretched by 1 / cos(camera pitch) so it reads at full height from the
## tilted camera. Eight facings picked by 45 degree sectors; a missing diagonal falls back to its side row.
## The gait depends on the game type. Cozy, exploration and RPG games walk by default (about 1.8 m/s, walk cycle)
## and run on Shift (about 4 m/s, run cycle); action games may run by default (move_speed about 4.2). The cycle is
## chosen by speed (run cycle from `run_cycle_from`), and speed_scale = speed / the cycle's natural speed, so the
## feet never slide. Never play the run cycle for the default gait of a cozy game.
## Sheet: one row per animation (idle_down, walk_up_left, run_right, ...), fixed cell size. The json beside it:
## {"cell_w", "cell_h", "frames", "rows", "fps": {"idle": 6, "walk": 10, "run": 14}, "height_m": 1.8,
##  "stride_m": {"walk": 0.94, "run": 1.68}, "cycles_per_s": {"walk": 1.25, "run": 1.75}}
## (stride_m = metres per cycle at height_m).

const DIRS := ["right", "up_right", "up", "up_left", "left", "down_left", "down", "down_right"]

@export var sheet: Texture2D
@export_file("*.json") var sheet_json := ""
## About door height / 1.15: 2.15 m next to 2.5 m doors.
@export var height_m := 2.15
## m/s, the default gait. Cozy / exploration / RPG: 1.8 (walk cycle). Action: about 4.2 (run cycle).
@export var move_speed := 1.8
## m/s while Shift is held (run cycle). Cozy: 4.0. Action: up to 1.8x the run cycle's natural speed.
@export var sprint_speed := 4.0
## m/s from which the run cycle plays instead of the walk cycle.
@export var run_cycle_from := 3.0
## Tests and agents drive the character with this instead of keys (x = screen right, y = screen up):
## length up to 1 is the default gait, above 1 sprints.
var input_override := Vector2.ZERO
var cam_basis := Basis()
var sprite: AnimatedSprite3D
var facing := "down"
var meta: Dictionary

func _ready() -> void:
	meta = JSON.parse_string(FileAccess.get_file_as_string(sheet_json))
	var shape := CollisionShape3D.new()
	var cap := CapsuleShape3D.new()
	cap.radius = 0.4
	cap.height = height_m - 0.2
	shape.shape = cap
	shape.position.y = cap.height / 2.0
	add_child(shape)
	sprite = AnimatedSprite3D.new()
	sprite.sprite_frames = _frames()
	sprite.billboard = BaseMaterial3D.BILLBOARD_FIXED_Y
	sprite.shaded = false
	sprite.alpha_cut = SpriteBase3D.ALPHA_CUT_DISCARD   # writes depth, so painted walls hide the character
	add_child(sprite)

## Called by the world with the paint camera's basis.
func setup(view_basis: Basis) -> void:
	cam_basis = view_basis
	var pitch := asin(clampf(-view_basis.z.y, -1.0, 1.0))
	var h := height_m / cos(pitch)
	sprite.pixel_size = h / float(meta.cell_h)
	sprite.position.y = h / 2.0
	_play("idle", 0.0)

func _frames() -> SpriteFrames:
	var sf := SpriteFrames.new()
	sf.remove_animation("default")
	for r in meta.rows.size():
		var anim: String = meta.rows[r]
		sf.add_animation(anim)
		sf.set_animation_speed(anim, _fps(anim.get_slice("_", 0)))
		for c in int(meta.frames):
			var at := AtlasTexture.new()
			at.atlas = sheet
			at.region = Rect2(c * meta.cell_w, r * meta.cell_h, meta.cell_w, meta.cell_h)
			sf.add_frame(anim, at)
	return sf

## fps in the json: one number, or a dictionary by kind ("walk").
func _fps(kind: String) -> float:
	var fps = meta.get("fps", 8.0)
	if fps is Dictionary:
		return float(fps.get(kind, 8.0))
	return float(fps)

## Ground speed (m/s) at which this kind's cycle keeps the feet still: stride (scaled to this height) x cycles/s.
## Without measurements: the generated cycles' typical values (walk 0.57, run 1.63 body heights per second).
func natural_speed(kind: String) -> float:
	var stride = meta.get("stride_m", {}).get(kind)
	if stride == null:
		return height_m * (1.63 if kind == "run" else 0.57)
	var cycles = meta.get("cycles_per_s", {}).get(kind, _fps(kind) / float(meta.frames))
	return float(stride) * height_m / float(meta.get("height_m", height_m)) * float(cycles)

## The cycle for a ground speed: the walk cycle below `run_cycle_from`, the run cycle from there.
func cycle_for(speed: float) -> String:
	if not sprite.sprite_frames.has_animation("run_down") or speed < run_cycle_from:
		return "walk"
	return "run"

func _play(kind: String, speed: float) -> void:
	var side := "left" if facing.ends_with("left") else ("right" if facing.ends_with("right") else facing)
	for anim in [kind + "_" + facing, kind + "_" + side, kind + "_down"]:
		if sprite.sprite_frames.has_animation(anim):
			sprite.play(anim)
			break
	sprite.speed_scale = 1.0 if kind == "idle" else clampf(speed / natural_speed(kind), 0.25, 4.0)

func _physics_process(delta: float) -> void:
	var v := input_override
	var speed := move_speed
	if v != Vector2.ZERO:
		speed = sprint_speed if v.length() > 1.05 else move_speed
	else:
		v = Input.get_vector("ui_left", "ui_right", "ui_down", "ui_up")
		if Input.is_key_pressed(KEY_SHIFT):
			speed = sprint_speed
	if v.length() < 0.1:
		speed = 0.0
	var right := Vector3(cam_basis.x.x, 0, cam_basis.x.z).normalized()
	var far := Vector3(-cam_basis.z.x, 0, -cam_basis.z.z).normalized()
	var dir := (right * v.x + far * v.y).normalized()
	velocity.x = dir.x * speed
	velocity.z = dir.z * speed
	velocity.y = 0.0 if is_on_floor() else velocity.y - 20.0 * delta
	move_and_slide()
	if speed > 0.0:
		facing = DIRS[wrapi(roundi(v.angle() / (PI / 4.0)), 0, 8)]
		_play(cycle_for(speed), speed)
	else:
		_play("idle", 0.0)

extends Node3D
## Painted 2.5D world: painted locations (painted_location.gd: Village, Cottage, ...), one player, one game camera.
## The game camera keeps the paint direction and only moves, so surfaces hidden in a painting stay hidden.
## Outdoors it shows about `view_width` metres and is clamped inside the painting with the REAL viewport aspect;
## rooms are framed whole. The clear colour is the current painting's edge colour.
## Proof shots from the real game window: run with `-- --shots=<dir>`; the player walks and runs through
## `shot_plan`, each step saves a JPG, then the game quits. Add your door walks to shot_plan.

@export var player_path: NodePath
@export var start_location: NodePath
## Metres across the screen outdoors: about 16 m, 7-8 hero heights.
@export var view_width := 16.0
## [name, screen input (x right, y up; length > 1 runs), seconds, "follow" or "full"]
@export var shot_plan: Array = [
	["start", Vector2.ZERO, 0.6, "follow"],
	["walk", Vector2(-1, 1).normalized(), 1.6, "follow"],
	["run", Vector2(-1.8, -0.6), 0.9, "follow"],
	["full_frame", Vector2.ZERO, 0.4, "full"],
]

@onready var game_cam: Camera3D = $GameCamera
@onready var player: CharacterBody3D = get_node(player_path)
var location: Node3D
var full_view := false

func _ready() -> void:
	location = get_node(start_location)
	if location.paint == null:
		_capture_mode()
		return
	game_cam.projection = Camera3D.PROJECTION_ORTHOGONAL
	game_cam.keep_aspect = Camera3D.KEEP_WIDTH
	game_cam.far = location.paint_cam.far
	game_cam.make_current()
	_enter(location)
	if player.has_method("setup"):
		player.setup(location.paint_cam.global_basis)
	for arg in OS.get_cmdline_user_args():
		if arg.begins_with("--shots="):
			_take_shots.call_deferred(arg.trim_prefix("--shots="))

## No painting yet: show the plain blockout through the paint camera, lit so its faces read for the painter
## (the painted game itself stays unshaded). Play it and capture the frame for the paint-over.
func _capture_mode() -> void:
	location.paint_cam.make_current()
	set_physics_process(false)
	if player.has_method("setup"):
		player.setup(location.paint_cam.global_basis)
	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-50, 20, 0)
	sun.light_energy = 1.2
	add_child(sun)
	var env := WorldEnvironment.new()
	env.environment = Environment.new()
	env.environment.background_mode = Environment.BG_COLOR
	env.environment.background_color = Color(0.1, 0.1, 0.12)
	env.environment.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	env.environment.ambient_light_color = Color.WHITE
	env.environment.ambient_light_energy = 0.55
	add_child(env)

## Doors call this: move the player into another painted location.
func go(to: Node3D, spawn: Vector3) -> void:
	location = to
	player.global_position = spawn
	player.velocity = Vector3.ZERO
	_enter(to)

func _enter(loc: Node3D) -> void:
	game_cam.global_basis = loc.paint_cam.global_basis
	RenderingServer.set_default_clear_color(loc.edge_color)
	_physics_process(0.0)

## Viewport height / width. The editor's game view and phones are not 16:9.
func _aspect() -> float:
	var vp := get_viewport().get_visible_rect().size
	return vp.y / vp.x if vp.x > 0 else 9.0 / 16.0

func _physics_process(_delta: float) -> void:
	var size: Vector2 = location.paint_size
	var aspect := _aspect()
	var fit := minf(size.x, size.y / aspect)   # the widest view that stays inside the painting
	var cam_basis: Basis = location.paint_cam.global_basis
	if location.frame_whole or full_view:
		game_cam.size = fit
		game_cam.global_position = location.paint_cam.global_position
		return
	# keep the player inside the painting (move along the ground, not through the air)
	var half := size / 2.0 - Vector2(1.0, 2.0)
	var c: Vector2 = location.plane(player.global_position)
	var clamped := c.clamp(-half, half)
	if clamped != c:
		var fwd := -cam_basis.z
		var far := Vector3(fwd.x, 0, fwd.z).normalized()
		player.global_position += cam_basis.x * (clamped.x - c.x) + far * (clamped.y - c.y) / far.dot(cam_basis.y)
	game_cam.size = minf(view_width, fit)
	var view := Vector2(game_cam.size, game_cam.size * aspect)
	var t: Vector2 = location.plane(player.global_position + Vector3(0, 1, 0)).clamp(-(size - view) / 2.0, (size - view) / 2.0)
	game_cam.global_position = location.paint_cam.global_position + cam_basis.x * t.x + cam_basis.y * t.y

func _take_shots(dir: String) -> void:
	DirAccess.make_dir_recursive_absolute(dir)
	for step in shot_plan:
		full_view = step[3] == "full"
		player.input_override = step[1]
		await get_tree().create_timer(step[2]).timeout
		await RenderingServer.frame_post_draw
		get_viewport().get_texture().get_image().save_jpg(dir.path_join(str(step[0]) + ".jpg"), 0.92)
	player.input_override = Vector2.ZERO
	full_view = false
	get_tree().quit()

"""Draw the blockout spec's wireframe (red) over the concept through the paint camera, no engine needed.
Fix block positions until the red lines sit on the concept's silhouettes, then build in the engine
(blockout_builder.gd reads the same spec). Camera settings: see cam.py. Needs Python with Pillow.
usage: python3 preview.py <concept.png> <blockout.json> <out.png>"""
import json, math, sys, os
sys.path.insert(0, os.path.dirname(__file__))
from cam import to_px, IMG
from PIL import Image, ImageDraw

def ry(v, deg):
    a = math.radians(deg); x, y, z = v
    return (x * math.cos(a) + z * math.sin(a), y, -x * math.sin(a) + z * math.cos(a))
def rx(v, deg):
    a = math.radians(deg); x, y, z = v
    return (x, y * math.cos(a) - z * math.sin(a), y * math.sin(a) + z * math.cos(a))

def rz(v, deg):
    a = math.radians(deg); x, y, z = v
    return (x * math.cos(a) - y * math.sin(a), x * math.sin(a) + y * math.cos(a), z)

def edges(o):
    k = o["kind"]; P = o.get("pos", [0, 0, 0]); yaw = o.get("yaw", 0); rxd = o.get("rot_x", 0); rzd = o.get("rot_z", 0)
    S = o.get("scale", [1, 1, 1])
    def w(v):
        v = (v[0] * S[0], v[1] * S[1], v[2] * S[2])
        v = ry(rx(rz(v, rzd), rxd), yaw)
        return (P[0] + v[0], P[1] + v[1], P[2] + v[2])
    if k == "box":
        sx, sy, sz = [s / 2 for s in o["size"]]
        c = [(x, y, z) for x in (-sx, sx) for y in (-sy, sy) for z in (-sz, sz)]
        E = [(a, b) for a in range(8) for b in range(a + 1, 8) if bin(a ^ b).count("1") == 1]
        return [(w(c[a]), w(c[b])) for a, b in E]
    if k == "prism":
        sx, sy, sz = [s / 2 for s in o["size"]]
        v = {"l0": (-sx, -sy, -sz), "r0": (sx, -sy, -sz), "a0": (0, sy, -sz), "l1": (-sx, -sy, sz), "r1": (sx, -sy, sz), "a1": (0, sy, sz)}
        E = [("l0", "r0"), ("r0", "a0"), ("a0", "l0"), ("l1", "r1"), ("r1", "a1"), ("a1", "l1"), ("l0", "l1"), ("r0", "r1"), ("a0", "a1")]
        return [(w(v[a]), w(v[b])) for a, b in E]
    if k in ("cyl", "sphere"):
        out = []
        if k == "cyl":
            rings = [(0, o["r_bot"]), (o["height"], o["r_top"])]
        else:
            r = o["radius"]; sy = o.get("sy", 1)
            rings = [(r * sy * math.sin(t), r * math.cos(t)) for t in (-0.9, -0.45, 0, 0.45, 0.9)]
        for (hy, r) in rings:
            pts = [(P[0] + r * math.cos(a * math.pi / 12), P[1] + hy, P[2] + r * math.sin(a * math.pi / 12)) for a in range(25)]
            out += list(zip(pts, pts[1:]))
        return out
    if k == "poly":
        pts = [(x, o["top"], z) for x, z in o["points"]]
        return list(zip(pts, pts[1:] + pts[:1]))
    return []

src, js, dst = sys.argv[1:4]
im = Image.open(src).convert("RGB").resize(IMG)
d = ImageDraw.Draw(im)
for o in json.load(open(js))["objects"]:
    for a, b in edges(o):
        d.line([to_px(a), to_px(b)], fill=(255, 30, 30), width=2)
im.save(dst)

skills.body:
# Real-Time Wet Surfaces (Value-Preserving Wet Materials)

## Outcome

Implement a real-time wetness effect in Summer Engine that can be applied to existing materials **without losing their configured values** (albedo, metallic, roughness, textures). The wet mask is driven by geometry alone (upward-facing surfaces collect wetness first), with a global/per-instance wet amount that can be animated at runtime. This follows the source technique: a pre-configured shader swap that keeps the standard material's values, fed by a custom-function bridge.

## When to Use

- Rain, wet caves, shorelines, or post-rain scenes where surfaces should darken and become glossy in real time.
- You need to wet many existing materials without re-authoring each one or losing its parameter values.
- You want a wetness amount that a gameplay system (rain zone, weather controller) can drive at runtime.

## Core Principle

The source technique's key idea is **separation of wetness from material authoring**: the wet logic is a self-contained graph/function that receives material values and injects a wet mask, so enabling wetness is a swap, not a rewrite.

How the source concepts map to Summer Engine:

| Source concept | Summer Engine equivalent |
|---|---|
| Standard lit material with retained values | `StandardMaterial3D` values copied into a `ShaderMaterial` by a one-time converter |
| Pre-configured shader-graph swap | Shared wet-enabled `.gdshader`; swap the material once, keep all parameter values |
| Custom-function node carrying values into the graph | Shader uniforms + instance uniforms (`set_instance_shader_parameter`) or `RenderingServer` global shader parameters for scene-wide wet state |
| Wet mask from geometry shape alone | Fragment mask from world-space normal up-facing component (`world_normal.y`), optionally broken up by world-position noise |
| Planned heightmap flow | Sample a heightmap texture and offset the wet mask along its gradient (future extension; not evidenced in source) |

**Constraint:** the engine cannot inject custom nodes into a `StandardMaterial3D` at runtime. The equivalent of "swap in the pre-configured shader while keeping all values" is a **converter that copies `StandardMaterial3D` parameters into the wet shader** (below). The alternative — leaving `StandardMaterial3D` untouched and overlaying wetness via decals or post-processing — does not match the source's material-preserving architecture and is not recommended here.

## Scene / Node Shape

```
Scene
├── Node3D (level)
│   ├── MeshInstance3D × N
│   │     └── Surface overrides: ShaderMaterial (wet-enabled shader, one shared .gdshader)
│   │           instance uniform `wet_amount` driven per object or globally
│   └── RainZone: Area3D (optional)
│         └── body_entered/exited signals → WetnessController
└── WetnessController: Node
      └── typed GDScript; animates wet_amount up while raining, down while drying
```

## Implementation Steps

### 1. Write the shared wet-enabled spatial shader

Preserve the PBR parameters as uniforms and compute the wet mask from geometry. Fragment-stage `NORMAL` is **view-space**, so pass a world-space normal from the vertex stage — otherwise the "upward-facing" mask rotates with the camera.

```glsl
shader_type spatial;
render_mode blend_mix, depth_draw_opaque, cull_back;

// Values copied from the original StandardMaterial3D by the converter
uniform vec4 albedo_color : source_color = vec4(1.0);
uniform sampler2D albedo_tex : filter_linear_mipmap;
uniform float metallic : hint_range(0.0, 1.0) = 0.0;
uniform float roughness : hint_range(0.0, 1.0) = 0.5;

// Wet state
instance uniform float wet_amount : hint_range(0.0, 1.0) = 0.0;
uniform float up_bias : hint_range(0.0, 1.0) = 0.35;    // wetness starts below fully-upward
uniform float darkening : hint_range(0.0, 1.0) = 0.55;  // how much wet albedo darkens
uniform float wet_roughness : hint_range(0.0, 1.0) = 0.08;
uniform float noise_scale = 8.0;
uniform sampler2D droplet_noise : filter_linear_mipmap, repeat_enable;

varying vec3 world_normal;
varying vec3 world_pos;

void vertex() {
    world_normal = (MODEL_MATRIX * vec4(NORMAL, 0.0)).xyz;
    world_pos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
}

void fragment() {
    vec4 alb := texture(albedo_tex, UV) * albedo_color;
    vec3 wn := normalize(world_normal);

    // Geometry-driven wet mask: upward-facing surfaces collect wetness first
    float facing := clamp(wn.y, 0.0, 1.0);
    float mask := smoothstep(up_bias, 1.0, facing) * wet_amount;

    // Break up the mask so it reads as weathering, not a flat shader pass
    mask *= 0.75 + 0.25 * texture(droplet_noise, world_pos.xz * noise_scale).r;

    ALBEDO = mix(alb.rgb, alb.rgb * (1.0 - darkening), mask);
    ROUGHNESS = mix(roughness, wet_roughness, mask);
    METALLIC = metallic;
    SPECULAR = mix(0.5, 0.9, mask);  // glossy film sells "wet"
}
```

Assumes near-uniform mesh scale; for heavily non-uniform scale, use the inverse-transpose normal transform instead of `MODEL_MATRIX` directly.

### 2. Convert existing materials while preserving their values

This is the source's "swap in the pre-configured shader; all values retained" step. Run once (editor tool or import-time), not per frame.

```gdscript
@tool
func convert_to_wet_material(src: StandardMaterial3D, wet_shader: Shader) -> ShaderMaterial:
    var m := ShaderMaterial.new()
    m.shader = wet_shader
    m.set_shader_parameter("albedo_color", src.albedo_color)
    m.set_shader_parameter("metallic", src.metallic)
    m.set_shader_parameter("roughness", src.roughness)
    if src.albedo_texture != null:
        m.set_shader_parameter("albedo_tex", src.albedo_texture)
    return m
```

Extend the copy list for any extra `StandardMaterial3D` properties your project uses (normal maps, emission, UV transforms). Keep the converter in one place so every wet-enabled material is produced identically.

### 3. Drive wetness at runtime with instance uniforms

```gdscript
class_name WetnessController
extends Node

@export var targets: Array[GeometryInstance3D] = []
@export_range(0.0, 1.0) var wet_rate: float = 0.15  # per second while raining
@export_range(0.0, 1.0) var dry_rate: float = 0.05  # per second after rain

var raining := false
var _wet: float = 0.0

func _process(delta: float) -> void:
    var goal := 1.0 if raining else 0.0
    var rate := wet_rate if raining else dry_rate
    _wet = move_toward(_wet, goal, rate * delta)
    for gi: GeometryInstance3D in targets:
        gi.set_instance_shader_parameter("wet_amount", _wet)
```

Use `Area3D` rain zones to toggle `raining` for objects inside them. For scene-wide weather without enumerating targets, register a global shader parameter once (`RenderingServer.global_shader_parameter_add("global_wet_amount", RenderingServer.GLOBAL_VAR_TYPE_FLOAT, 0.0)`) and set it per frame with `RenderingServer.global_shader_parameter_set`; read it in the shader instead of the instance uniform.

### 4. Planned extension: heightmap-guided flow

The source author states heightmap support so wetness flows along map bumps is **planned, not shipped**. To implement it: sample a heightmap texture in the fragment stage and bias the wet mask along its gradient (e.g., offset `world_pos.xz` lookups downhill using the height texture derivatives) so streaks follow surface relief. Do not treat this as part of the evidenced technique.

## Tunables

| Parameter | Typical Value | Notes |
|---|---|---|
| `wet_amount` | 0–1, animated | Instance uniform or global shader parameter |
| `up_bias` | 0.35 | Lower = walls and slopes also wet; higher = only flat tops |
| `darkening` | 0.4–0.6 | Wet albedo multiplier = `1.0 - darkening` |
| `wet_roughness` | 0.05–0.15 | Lower = glassy puddle look |
| `noise_scale` | 4–16 | World-space breakup frequency |
| `wet_rate` / `dry_rate` | 0.15 / 0.05 per s | Asymmetric rates feel natural (wets fast, dries slow) |

## Failure Modes & Gotchas

- **View-space normal mistake:** using fragment `NORMAL` directly makes the up-facing mask rotate with the camera. Always pass world normal from `vertex()` via a varying.
- **Expecting in-place injection:** the engine cannot add wet logic to a live `StandardMaterial3D`. The value-preserving step is the one-time conversion, not runtime patching.
- **Duplicate shaders per material:** keep ONE shared `.gdshader`; per-material differences live in uniforms, per-object state in instance uniforms. Otherwise you pay shader compilation and draw-call overhead.
- **Over-darkening:** on already-dark albedos, clamp the darkened result or lower `darkening`.
- **Transparent/unshaded materials:** out of scope; this skill targets opaque PBR surfaces.
- **Skinned meshes:** verify the `MODEL_MATRIX` world-normal transform still behaves with skeletal animation before relying on the up-facing mask.

## Verification

1. With `wet_amount = 0`, converted materials render identically to their original `StandardMaterial3D` values (compare albedo/roughness response under a fixed light).
2. Raising `wet_amount` darkens and glosses upward-facing surfaces; downward-facing and underside faces stay mostly dry.
3. Rotating the camera does NOT shift the wet mask boundaries (confirms world-space normal).
4. `WetnessController` animates wet/dry transitions smoothly with no per-material edits during play.
5. Multiple meshes share one shader resource; adding wet-enabled objects does not add new shader variants.

## Confidence

`extracted` — the architecture (material-preserving wet swap, custom-function value bridge, geometry-only mask, planned heightmap flow) comes from a public post that showed the technique in another engine; no code was published. The mapping, shader, and scripts here are engineering guidance consistent with that post, **not** source-extracted implementation and **not** verified inside Summer Engine.

## Evidence

- A public X post describing the technique (demo video only, no code).

files.content:
# A complete minimal Summer App

A working code app: shared notes for a playtest. Copy it, rename things, then grow it.
It shows every piece an app needs: the manifest, loading the SDK and kit, waiting for
the host, shared data (list, put, live changes), who changed a row (person or agent),
an edit flow (dialog + form with setValues), status badges, an error with Try again, the
page declaration, an agent event, an agent tool and frame-move state.

Publish it with `apps.publish({ appId, files, manifest, note })` where `files` holds
`index.html` and `app.js` as `{ path, content }`. The page, sections, inputs,
table, notice and empty text are kit components (`apps.guide({ section: "kit" })`, or
`/summer-ui/v1/catalog.json` on the app host); no app CSS is needed.

## The manifest (send it as `manifest`)

```json
{
  "name": "Playtest notes",
  "purpose": "Tester notes per level. Notes live in this app's shared data.",
  "permissions": ["data"],
  "collections": {
    "notes": {
      "description": "One remark from a playtest",
      "fields": {
        "text": { "type": "string", "required": true, "description": "What the tester said" },
        "level": { "type": "string", "description": "Level name, e.g. bridge" },
        "status": { "type": "string", "description": "open or fixed" },
        "author": { "type": "string", "description": "Who added it" }
      }
    }
  },
  "agentEvents": ["note.added"],
  "agentTools": [
    {
      "name": "add_note",
      "description": "Add a playtest note",
      "input": {
        "type": "object",
        "properties": { "text": { "type": "string" }, "level": { "type": "string" } },
        "required": ["text"]
      }
    }
  ]
}
```

## index.html

```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Playtest notes</title>
<!-- Both are ES modules on the app's own host (apps.summerengine.app). Root paths, type="module". -->
<script type="module" src="/summer-sdk/v1.js"></script>
<script type="module" src="/summer-ui/v1/ui.js"></script>
</head>
<body>
<summer-page heading="Playtest notes" purpose="Tester notes per level, shared with your team and your agent.">
  <summer-button slot="actions" id="add" variant="primary" icon="plus">Add note</summer-button>
  <summer-section heading="Notes">
    <summer-notice id="error" tone="error" action="Try again" action-icon="refresh-cw" hidden></summer-notice>
    <summer-table id="table" row-key="id" sortable clickable loading
      empty-text="No notes yet. Add the first one, or ask your agent to add the testers' notes."></summer-table>
  </summer-section>
  <summer-dialog id="dialog" heading="Note" description="Shared with your team and your agent.">
    <summer-form id="form" submit-label="Save note">
      <summer-text-input label="Note" name="text" multiline required></summer-text-input>
      <summer-grid columns="2">
        <summer-text-input label="Level" name="level" placeholder="bridge"></summer-text-input>
        <summer-select label="Status" name="status" options='[{"value":"open","label":"Open"},{"value":"fixed","label":"Fixed"}]'></summer-select>
      </summer-grid>
    </summer-form>
  </summer-dialog>
</summer-page>
<!-- app.js runs after the SDK module (module scripts run in order). -->
<script type="module" src="app.js"></script>
</body>
</html>
```

## app.js

```js
const notes = summer.data.collection("notes");
const info = await summer.ready;   // { viewer: { userId, name }, params, restored, ... }
const $ = (id) => document.getElementById(id);
const table = $("table"), dialog = $("dialog"), form = $("form"), error = $("error");
let editing = null;                 // the note id being edited, or null for a new one

table.columns = [
  { key: "text", label: "Note", priority: "primary" },
  { key: "level", label: "Level" },
  { key: "status", label: "Status", badges: { open: "warn", fixed: "ok" } },   // one badge tone per value
  { key: "by", label: "By", type: "muted" },
];

async function load() {
  table.setAttribute("loading", "");
  try {
    const page = await notes.list({ limit: 500 });   // removed notes are never listed
    table.rows = page.records.map((r) => ({
      id: r.recordId,
      ...r.data,
      // createdBy: who made the row ({ userId, kind: "person" | "agent" | "seed", agent?, via? });
      // later edits do not change it (actor is the last writer). Seed rows have no author.
      by: r.createdBy?.kind === "agent" ? `${r.createdBy.agent ?? "Agent"} (agent)` : r.data.author ?? "",
    }));
    error.hidden = true;
  } catch (e) {
    error.setAttribute("text", `Could not load notes: ${e.message}`);
    error.hidden = false;
  } finally {
    table.removeAttribute("loading");
  }
}
error.addEventListener("action", load);   // the notice's "Try again" button

function openEditor(row) {
  editing = row?.id ?? null;
  form.setValues(row ?? { text: "", level: "", status: "open" });
  dialog.show();
}
$("add").addEventListener("click", () => openEditor(null));
table.addEventListener("summer-row", (event) => openEditor(event.detail.row));   // click a row to edit

form.addEventListener("submit", async (event) => {
  const { text, level, status } = event.detail.values;   // numbers come as numbers, empty as null
  form.setAttribute("busy", "");
  try {
    const id = editing ?? crypto.randomUUID();
    await notes.put(id, { text, level: level ?? "", status: status ?? "open", author: info.viewer.name ?? "someone" });
    if (!editing) await summer.agent.send("note.added", { id, text, level });   // name is in manifest.agentEvents
    dialog.close();
    summerUI.toast("Note saved");
  } catch (e) {
    form.setAttribute("error", e.message);
  } finally {
    form.removeAttribute("busy");
  }
});

// Live: every change by a teammate or an agent arrives as { revision, actor, ops } (or { reset: true }).
notes.subscribe(() => load());

// Agent tool: apps.call({ appId, tool: "add_note", input: { text, level } }) runs this while the app is open.
// Its writes are recorded as the calling agent's (actor.kind "agent", via "agent-tool").
summer.agent.tool("add_note", async ({ text, level }, { agent }) => {
  const id = crypto.randomUUID();
  await notes.put(id, { text, level: level ?? "", status: "open", author: agent });
  return { id };
});

// What agents can read with apps.page and use with apps.use_page.
summer.page.declare({ actions: [{ id: "add", label: "Add note", run: () => openEditor(null) }] });

// Frame moves: Studio moves an idle app to a fresh frame every few minutes. Shared data survives on
// its own; keep only UI state, such as an open editor.
summer.app.onSnapshot(() => (dialog.hasAttribute("open") ? { editing, values: form.values } : null));
if (info.restored?.values) {
  editing = info.restored.editing;
  form.setValues(info.restored.values);
  dialog.show();
}

load();
```

Playing sound with Web Audio instead of `<audio>`? Wrap it so the frame is not moved
mid-sound: `summer.app.busy(true)` when it starts, `summer.app.busy(false)` in the
source's `onended`.

## The agent side of the same app

```json
{ "appId": "<id>", "ops": [{ "op": "put", "collection": "notes", "recordId": "n-1", "data": { "text": "Boss fight too long", "level": "boss", "status": "open", "author": "agent" } }] }
```

That is an `apps.write_data` input: it works with the app closed, and the open app shows it
through `notes.subscribe`. `apps.tools` and `apps.read_data` return the
`collections` above, so an agent knows the record shape.

// 3D Fractal Brownian Motion noise — used by fire, dissolve, smoke, magic-glow.
// Include with: #include "res://addons/vfx/_building-blocks/noise-3d-fbm.gdshaderinc"

float hash3(vec3 p) {
    p = fract(p * vec3(443.8975, 397.2973, 491.1871));
    p += dot(p, p.yxz + 19.19);
    return fract((p.x + p.y) * p.z);
}

float noise3(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    float n000 = hash3(i + vec3(0.0, 0.0, 0.0));
    float n100 = hash3(i + vec3(1.0, 0.0, 0.0));
    float n010 = hash3(i + vec3(0.0, 1.0, 0.0));
    float n110 = hash3(i + vec3(1.0, 1.0, 0.0));
    float n001 = hash3(i + vec3(0.0, 0.0, 1.0));
    float n101 = hash3(i + vec3(1.0, 0.0, 1.0));
    float n011 = hash3(i + vec3(0.0, 1.0, 1.0));
    float n111 = hash3(i + vec3(1.0, 1.0, 1.0));

    float x00 = mix(n000, n100, f.x);
    float x10 = mix(n010, n110, f.x);
    float x01 = mix(n001, n101, f.x);
    float x11 = mix(n011, n111, f.x);

    float y0 = mix(x00, x10, f.y);
    float y1 = mix(x01, x11, f.y);

    return mix(y0, y1, f.z);
}

float fbm3(vec3 p) {
    float v = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    for (int i = 0; i < 4; i++) {
        v += amp * noise3(p * freq);
        freq *= 2.0;
        amp *= 0.5;
    }
    return v;
}

skills.body:
# fire — Animated Particle Flames

Fire in games is almost never a video clip and never an AI-generated sprite. It's a pile of additive billboard quads emitted from a cone, each running a noise-distorted UV through a hot color ramp (red → orange → yellow → smoky alpha-out). Think Skyrim torches, Doom Eternal's pyre, BotW's bonfires — all built from this same recipe with different dials. This skill writes the shader, the controller, and the node tree, then wires them into the open scene. Authoring, not generating.

## When to use

- "Add fire to this torch."
- "Make a campfire / bonfire / hearth flame."
- "Light the brazier."
- "I need a candle flame on this candlestick."
- "The dragon needs a flame breath" (use this for the persistent emitter; pair with a one-shot `vfx-muzzle-flash` for the burst).
- The player set something on fire and you need a continuous, physically-anchored flame.

## When NOT to use

- The user wants an object to *burn away* (mesh disintegrating with a fire edge) — route to `vfx-dissolve`. Fire is a separate effect; pair them.
- The user wants smoke without flame — go straight to `vfx-smoke`. (Most fires want a smoke trail above; spawn this recipe and add `vfx-smoke` on top.)
- The user wants a one-frame muzzle flash from a gun — that's `vfx-muzzle-flash`, not fire.
- The user wants 2D fire on a UI element — use `canvas_item` shader; this recipe is `spatial`/`particles`.
- The user wants stylized magic flame (blue, purple, ethereal) — use this recipe and load the `magic-fire` variant in the cookbook below.

## Recipe

### 1. Files to create

```
addons/vfx/_building-blocks/noise-3d-fbm.gdshaderinc   # copy from this skill FIRST
addons/vfx/fire/fire.gdshader              # spatial shader for the visual quad
addons/vfx/fire/fire_process.gdshader      # particle shader for the simulation
addons/vfx/fire/fire_controller.gd          # parameter dials + lifetime
addons/vfx/fire/fire.tscn                   # reusable scene (instantiate per torch)
```

`fire.gdshader` `#include`s the FBM noise file. A missing include is a hard compile
error, so copy `_building-blocks/noise-3d-fbm.gdshaderinc` from this skill into
`res://addons/vfx/_building-blocks/` before writing the shader.

### 2. Visual shader code

`addons/vfx/fire/fire.gdshader`:

```glsl
shader_type spatial;
render_mode unshaded, blend_add, depth_draw_never, cull_disabled, shadows_disabled;

#include "res://addons/vfx/_building-blocks/noise-3d-fbm.gdshaderinc"

uniform vec4 color_hot   : source_color = vec4(1.0, 0.95, 0.55, 1.0);
uniform vec4 color_mid   : source_color = vec4(1.0, 0.45, 0.10, 1.0);
uniform vec4 color_cool  : source_color = vec4(0.85, 0.10, 0.02, 1.0);
uniform vec4 color_smoke : source_color = vec4(0.05, 0.04, 0.04, 0.0);

uniform float noise_scale     : hint_range(0.5, 8.0)  = 3.0;
uniform float noise_speed     : hint_range(0.0, 4.0)  = 1.4;
uniform float distortion      : hint_range(0.0, 0.6)  = 0.20;
uniform float emission_energy : hint_range(0.0, 8.0)  = 3.5;
uniform float soft_edge       : hint_range(0.01, 0.5) = 0.20;

// INSTANCE_CUSTOM is vertex-stage only, so carry what fragment() needs across.
varying float age;
varying float seed;

void vertex() {
    // Billboard toward the camera, keeping per-particle rotation (INSTANCE_CUSTOM.x)
    // and per-particle scale. The bare `VIEW_MATRIX * mat4(INV_VIEW_MATRIX[0..2],
    // MODEL_MATRIX[3])` form throws both away — this mirrors what Godot's own
    // BILLBOARD_PARTICLES generator emits (scene/resources/material.cpp:1313-1334).
    mat4 mat_world = mat4(
        normalize(INV_VIEW_MATRIX[0]),
        normalize(INV_VIEW_MATRIX[1]),
        normalize(INV_VIEW_MATRIX[2]),
        MODEL_MATRIX[3]);
    mat_world = mat_world * mat4(
        vec4(cos(INSTANCE_CUSTOM.x), -sin(INSTANCE_CUSTOM.x), 0.0, 0.0),
        vec4(sin(INSTANCE_CUSTOM.x),  cos(INSTANCE_CUSTOM.x), 0.0, 0.0),
        vec4(0.0, 0.0, 1.0, 0.0),
        vec4(0.0, 0.0, 0.0, 1.0));
    MODELVIEW_MATRIX = VIEW_MATRIX * mat_world * mat4(
        vec4(length(MODEL_MATRIX[0].xyz), 0.0, 0.0, 0.0),
        vec4(0.0, length(MODEL_MATRIX[1].xyz), 0.0, 0.0),
        vec4(0.0, 0.0, length(MODEL_MATRIX[2].xyz), 0.0),
        vec4(0.0, 0.0, 0.0, 1.0));
    MODELVIEW_NORMAL_MATRIX = mat3(MODELVIEW_MATRIX);

    // CUSTOM.x is the rotation angle, NOT the age. The age lives in CUSTOM.y
    // (it counts up by DELTA/LIFETIME) and CUSTOM.w holds the lifetime scale.
    age  = clamp(INSTANCE_CUSTOM.y / max(INSTANCE_CUSTOM.w, 0.0001), 0.0, 1.0);
    seed = fract(sin(float(INSTANCE_ID) * 12.9898) * 43758.5453);
}

void fragment() {
    // Distort UVs with scrolling 3D noise so the flame writhes.
    vec3 np = vec3(UV * noise_scale, TIME * noise_speed + seed * 10.0);
    float n = fbm3(np);
    vec2 uv = UV + vec2(n - 0.5) * distortion;

    // Soft round mask, hottest at the bottom-center, cooler toward the top.
    vec2 c = uv - vec2(0.5, 0.15);
    float r = length(c * vec2(1.0, 0.55));
    float mask = smoothstep(0.55, 0.55 - soft_edge, r);

    // Color ramp by particle age (0 = hot bright, 1 = smoky alpha-out).
    vec4 col;
    if (age < 0.33) {
        col = mix(color_hot, color_mid, age / 0.33);
    } else if (age < 0.75) {
        col = mix(color_mid, color_cool, (age - 0.33) / 0.42);
    } else {
        col = mix(color_cool, color_smoke, (age - 0.75) / 0.25);
    }

    // Add the noise as a brightness modulation so flames flicker.
    float flicker = mix(0.6, 1.2, n);

    // `render_mode unshaded` outputs ALBEDO and discards EMISSION entirely
    // (scene_forward_clustered.glsl:2962 — `frag_color = vec4(albedo, alpha)`
    // under MODE_UNSHADED), so the HDR boost that drives glow lives in ALBEDO.
    ALBEDO = col.rgb * flicker * emission_energy * (1.0 - age * 0.5);
    ALPHA = col.a * mask * (1.0 - age * age);
}
```

### 3. Particle process shader (optional)

For most fires the built-in `ParticleProcessMaterial` is fine. Drop in this custom shader only if you need turbulence beyond the standard params:

`addons/vfx/fire/fire_process.gdshader`:

```glsl
shader_type particles;

uniform float rise_speed   : hint_range(0.1, 6.0) = 1.8;
uniform float spread_angle : hint_range(0.0, 1.5) = 0.35;
uniform float lifetime_var : hint_range(0.0, 1.0) = 0.25;

// `rand_from_seed()` is generated into ParticleProcessMaterial's own shader; it is
// NOT a built-in you can call from a hand-written particles shader
// ("SHADER ERROR: No matching function found for: 'rand_from_seed'"). Supply one.
uint hash_u(uint x) {
    x ^= x >> 16u;
    x *= 0x7feb352du;
    x ^= x >> 15u;
    x *= 0x846ca68bu;
    x ^= x >> 16u;
    return x;
}

float rnd(uint s) {
    return float(hash_u(s) & 0x00ffffffu) / 16777216.0;
}

void start() {
    uint s = RANDOM_SEED + INDEX * 747796405u;

    // Random spawn within a small disc.
    float r  = sqrt(rnd(s + 7u)) * 0.18;
    float th = rnd(s + 11u) * 6.2831853;
    TRANSFORM[3].xyz = vec3(cos(th) * r, 0.0, sin(th) * r);

    // Initial velocity: mostly up, slight cone.
    vec3 dir = vec3(
        (rnd(s + 13u) - 0.5) * spread_angle,
        1.0,
        (rnd(s + 17u) - 0.5) * spread_angle
    );
    VELOCITY = normalize(dir) * rise_speed;

    // LIFETIME is read-only ("SHADER ERROR: Constants cannot be modified") and there
    // is no TOTAL_LIFETIME. Stagger lifetimes the way ParticleProcessMaterial does:
    // keep a per-particle lifetime scale in CUSTOM.w and retire the particle when
    // the age in CUSTOM.y passes it.
    CUSTOM = vec4(0.0);
    CUSTOM.w = 1.0 + (rnd(s + 19u) - 0.5) * 2.0 * lifetime_var;
    CUSTOM.z = rnd(s + 23u); // per-particle seed
}

void process() {
    // CUSTOM.x = rotation angle, .y = age, .z = per-particle seed, .w = lifetime scale.
    CUSTOM.y += DELTA / LIFETIME;
    if (CUSTOM.y > CUSTOM.w) {
        ACTIVE = false;
    }
    float age = clamp(CUSTOM.y / max(CUSTOM.w, 0.0001), 0.0, 1.0);

    // Rise + small horizontal sway.
    VELOCITY.y += DELTA * 0.6;
    VELOCITY.x += sin(TIME * 2.0 + CUSTOM.z * 6.28) * DELTA * 0.4;
    VELOCITY.z += cos(TIME * 2.3 + CUSTOM.z * 6.28) * DELTA * 0.4;

    // Shrink as it ages.
    float scale = mix(1.0, 0.35, age);
    TRANSFORM[0].xyz = vec3(scale, 0.0, 0.0);
    TRANSFORM[1].xyz = vec3(0.0, scale, 0.0);
    TRANSFORM[2].xyz = vec3(0.0, 0.0, scale);
}
```

### 4. GDScript controller

`addons/vfx/fire/fire_controller.gd`:

```gdscript
@tool
class_name FireController
extends GPUParticles3D

@export_group("Flame size")
@export_range(0.05, 5.0) var flame_height: float = 1.2 :
    set(v): flame_height = v; _apply()
@export_range(0.05, 3.0) var flame_radius: float = 0.35 :
    set(v): flame_radius = v; _apply()

@export_group("Flame intensity")
@export_range(8, 1024) var particle_count: int = 96 :
    set(v): particle_count = v; _apply()
@export_range(0.2, 4.0) var flame_lifetime: float = 1.4 :
    set(v): flame_lifetime = v; _apply()
@export_range(0.0, 8.0) var emission_energy: float = 3.5 :
    set(v): emission_energy = v; _apply()

@export_group("Color")
@export var color_hot:   Color = Color(1.0, 0.95, 0.55)
@export var color_mid:   Color = Color(1.0, 0.45, 0.10)
@export var color_cool:  Color = Color(0.85, 0.10, 0.02)

func _ready() -> void:
    one_shot = false
    explosiveness = 0.0
    _apply()

func _apply() -> void:
    amount = particle_count
    lifetime = flame_lifetime

    var pm := process_material as ParticleProcessMaterial
    if pm:
        pm.emission_shape = ParticleProcessMaterial.EMISSION_SHAPE_SPHERE
        pm.emission_sphere_radius = flame_radius
        pm.direction = Vector3.UP
        pm.spread = 12.0
        pm.initial_velocity_min = flame_height * 0.9
        pm.initial_velocity_max = flame_height * 1.4
        pm.gravity = Vector3.ZERO
        pm.scale_min = flame_radius * 1.1
        pm.scale_max = flame_radius * 1.6

    if draw_pass_1:
        var mesh := draw_pass_1 as QuadMesh
        var mat := mesh.surface_get_material(0) as ShaderMaterial
        if mat:
            mat.set_shader_parameter("color_hot",   color_hot)
            mat.set_shader_parameter("color_mid",   color_mid)
            mat.set_shader_parameter("color_cool",  color_cool)
            mat.set_shader_parameter("emission_energy", emission_energy)

func extinguish(fade_seconds: float = 0.5) -> void:
    var t := create_tween()
    t.tween_property(self, "amount_ratio", 0.0, fade_seconds)
    t.tween_callback(queue_free)
```

### 5. Node tree

```
GPUParticles3D ("Fire") [script: fire_controller.gd]
  ├── process_material: ParticleProcessMaterial (or ShaderMaterial w/ fire_process.gdshader)
  └── draw_pass_1: QuadMesh (size Vector2(1, 1))
        └── material: ShaderMaterial (shader: fire.gdshader)
```

`process_material` and `draw_pass_1` are resource properties on the one node, not
child nodes. `surface_material_override` belongs to `MeshInstance3D` and does not
apply here — a draw pass mesh carries its material in `Mesh.material`.

Add an OmniLight3D as a sibling (parented to the same anchor as the GPUParticles3D, NOT under it) for proper light cast. Recommended: `light_color = Color(1.0, 0.6, 0.25)`, `light_energy = 1.6`, `omni_range = 6.0`. Pulse it lightly via the controller for free atmosphere.

### 6. Wire it in

Write the three files, then wire everything in ONE `summer_run_script` call with
an explicit `scenePath` — transactional (rollback on a mid-script error), no
`.tres` sidecar files needed because the script builds the resources directly:

```
summer_write_file(path="res://addons/vfx/_building-blocks/noise-3d-fbm.gdshaderinc", content="<from this skill>", create_only=true)
summer_write_file(path="res://addons/vfx/fire/fire.gdshader", content="<section 2>", create_only=true)
summer_write_file(path="res://addons/vfx/fire/fire_controller.gd", content="<section 4>", create_only=true)

summer_run_script(scenePath="res://main.tscn", source="""
func run(ctx):
    var anchor = ctx.find("Torch")
    var fire = ctx.add_node("GPUParticles3D", "Fire", anchor)
    fire.set_script(load("res://addons/vfx/fire/fire_controller.gd"))
    fire.process_material = ParticleProcessMaterial.new()   # controller configures it on _ready
    var quad := QuadMesh.new()
    quad.size = Vector2(1, 1)
    var mat := ShaderMaterial.new()
    mat.shader = load("res://addons/vfx/fire/fire.gdshader")
    quad.material = mat
    fire.draw_pass_1 = quad
    fire.set("flame_height", 1.2)
    fire.set("flame_radius", 0.35)
    fire.set("particle_count", 96)
    ctx.add_node("OmniLight3D", "FireLight", anchor, {
        "light_color": Color(1.0, 0.6, 0.25), "light_energy": 1.6, "omni_range": 6.0})
    ctx.save_scene()
""")
```

`ParticleProcessMaterial` is a Material, not a Node: the script assigns it to
`process_material`, it is never a child. `ctx.add_node` sets owners for you. Take
a `summer_world_snapshot` before, and verify after with `summer_snapshot_diff`
(exactly `Fire` + `FireLight` added) plus a `summer_screenshot` — flames are
pixels, judge them as pixels.

### 6a. Verify

Every file this recipe writes is compiled code. Check it before claiming the fire works.

```
summer_get_script_errors          # fire_controller.gd parsed?
summer_play
summer_get_debugger_errors        # shader compile errors surface here at runtime
summer_stop
```

A missing `noise-3d-fbm.gdshaderinc` and an un-copied shader both show up as compile
errors, not as an invisible flame. Read the errors before tuning any dial.

### 7. Parameters to tune

| Parameter | Range | Effect |
|---|---|---|
| `particle_count` (`amount`) | 32–512 | density of the flame, perf cost is linear |
| `flame_lifetime` | 0.5–3.0 s | how long each particle lives before fade |
| `flame_height` | 0.2–4.0 | initial upward velocity → height of the column |
| `flame_radius` | 0.05–2.0 | spawn disc + per-particle scale |
| `emission_energy` | 0.0–8.0 | how much it blooms in the post-process |
| `noise_scale` | 0.5–8.0 | small = wide flowing tongues; large = fine flicker |
| `noise_speed` | 0.0–4.0 | how fast the flame moves |
| `distortion` | 0.0–0.6 | how warped the silhouette gets |
| `color_hot/mid/cool` | Color | the ramp; shift toward blue/green/purple for magic |

